"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["12810"],{90367(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.calendario_dias_uteis.conflito_de_concorrencia","status":409,"titulo":"Outra altera\xe7\xe3o concorrente modificou o mesmo calend\xe1rio ou o calend\xe1rio vigente"},"descricao":{"codigo":"uniplus.configuracao.calendario_dias_uteis.conflito_de_concorrencia","requisitos":[],"oQueAconteceu":["Duas opera\xe7\xf5es sobre o calend\xe1rio de dias \xfateis esbarraram numa disputa\\nconcorrente: marcar um calend\xe1rio como vigente e incluir um dia n\xe3o \xfatil avulso\\nnum calend\xe1rio existente.","Ao **marcar como vigente**, o conflito cobre dois cen\xe1rios distintos:","- **duas ativa\xe7\xf5es concorrentes** disputando o mesmo \\"vigente = true\\" ao\\n  mesmo tempo (refor\xe7ado por uma exclusion constraint de banco: no m\xe1ximo um\\n  calend\xe1rio vigente por vez); ou\\n- **este mesmo calend\xe1rio foi modificado concorrentemente** \u2014 por exemplo,\\n  removido \u2014 entre a leitura e a grava\xe7\xe3o desta opera\xe7\xe3o.","Ao **incluir um dia n\xe3o \xfatil avulso**, o conflito acontece quando o mesmo\\ncalend\xe1rio foi removido, teve a vig\xeancia alterada ou recebeu **outra inclus\xe3o\\nconcorrente** entre a leitura e a grava\xe7\xe3o desta inclus\xe3o (cada inclus\xe3o marca\\no calend\xe1rio como alterado). A inclus\xe3o que conflita n\xe3o grava o dia.","A remo\xe7\xe3o de um calend\xe1rio **n\xe3o** emite este c\xf3digo: a disputa dela com outra\\naltera\xe7\xe3o recebe o tratamento gen\xe9rico de conflito de concorr\xeancia (409).","Nos casos que emitem este c\xf3digo a opera\xe7\xe3o n\xe3o decide sozinha qual das duas\\naltera\xe7\xf5es concorrentes prevalece: ela recusa, e quem chamou tenta de novo com\\no estado atualizado."],"comoResolver":["Tente a opera\xe7\xe3o novamente. Se o conflito persistir, confira o estado atual\\ndo calend\xe1rio e de qual \xe9 o vigente antes de repetir a chamada \u2014 outra altera\xe7\xe3o\\npode ter chegado primeiro.","Na inclus\xe3o de um dia n\xe3o \xfatil, se o calend\xe1rio foi removido pela outra opera\xe7\xe3o,\\na nova tentativa responde [calend\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.calendario_dias_uteis.nao_encontrado):\\nescolha outro calend\xe1rio ou cadastre um novo."],"ondeAparece":["Marcar um calend\xe1rio de dias \xfateis como vigente, quando outra ativa\xe7\xe3o concorrente disputa o mesmo instante","Inclus\xe3o de um dia n\xe3o \xfatil avulso, quando o mesmo calend\xe1rio foi removido, teve a vig\xeancia alterada ou recebeu outra inclus\xe3o concorrente"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Calendario dias uteis"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);